// Cross-language consistency runner for the C++ binding.
//
// Executes the hermetic cases from `tests/consistency/cases.json` (generated by
// `tests/consistency/generate_cases.py`) and asserts the same golden
// expectations as the python / nodejs / go / java / .NET runners, so a change to
// the shared manifest that only one binding notices shows up here too.
//
// Three steps, mirroring `java/src/test/java/com/kcl/ConsistencyTest.java`:
//
//   1. Load the manifest and check `version == 1`.
//   2. Ask `list_method` once for the RPC surface of the linked core. Cases
//      marked `new_core` are *skipped*, not failed, when the core does not
//      advertise their RPC: the six newer RPCs (the five `Generate*` plus
//      `FormatTestReport`) only exist on a newer `libkcl` than the one this
//      crate's `kcl-api` pin can serve, and a runner that failed on them would
//      be red for a reason that has nothing to do with the binding.
//   3. Dispatch on the `rpc` field and compare only the fields that actually
//      appear under `expect`, so a manifest that grows a field needs no change
//      here.
//
// Expectations are read from the manifest, never hardcoded. Paths in
// `parse_args.paths` are pinned repo-relative by the generator and are resolved
// against the repository root, so the runner does not depend on the working
// directory ctest happens to pick.
//
// JSON comes from `kcl_facade.hpp`, so this file builds and runs identically
// whether CMake found nlohmann/json or fell back to the bundled parser; the
// handful of adapters below are the only place the two spellings differ.
//
// Plain <cassert>-style CHECK macro like tests/test_api.cpp, no external
// dependencies.

#include "kcl_facade.hpp"
#include "kcl_lib.hpp"

#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

// The manifest lives at the repository root, two levels above `cpp/`. Prefer an
// explicit override so the runner can be pointed at a copy from anywhere.
#ifndef KCL_CONSISTENCY_CASES
#define KCL_CONSISTENCY_CASES "../../tests/consistency/cases.json"
#endif

#define CHECK(cond)                                                            \
    do {                                                                       \
        if (!(cond)) {                                                         \
            std::cerr << "CHECK failed: " << #cond << " at " << __FILE__ << ":" \
                      << __LINE__ << std::endl;                                \
            return false;                                                      \
        }                                                                      \
    } while (0)

namespace {

namespace fs = std::filesystem;

/// Outcome of a consistency case that the linked core cannot run.
struct SkipCase : std::runtime_error {
    explicit SkipCase(const std::string& reason)
        : std::runtime_error(reason)
    {
    }
};

// ---------------------------------------------------------------------------
// Backend-agnostic JSON adapters
//
// `kcl_lib::JsonValue` is `nlohmann::ordered_json` or the facade's bundled
// `Json`, and the two differ in a few spellings. Everything the walk below
// needs is already ported in `kcl_lib::detail` (`json_find`, `for_each_member`,
// `for_each_item`, `json_string`, `json_scalar_text`); only the four gaps below
// are filled in here.
// ---------------------------------------------------------------------------

/// Whole-document parse. `detail::parse_json_stream` is deliberately a
/// line-splitting helper for the runtime's one-JSON-value-per-line output, so
/// it cannot read the pretty-printed manifest; the bundled parser accepts a
/// stream and the first document of a single-document file is the file.
inline kcl_lib::JsonValue parse_json_document(const std::string& text)
{
#ifdef KCL_LIB_HAS_NLOHMANN
    // `allow_exceptions = false` keeps a malformed manifest from throwing
    // nlohmann's own exception type past the runner.
    auto parsed = nlohmann::ordered_json::parse(text, nullptr, false);
    if (parsed.is_discarded()) {
        throw kcl_lib::KclError("kcl: invalid JSON result: " + text.substr(0, 120));
    }
    return parsed;
#else
    auto docs = kcl_lib::detail::JsonParser(text.data(), text.data() + text.size()).parse_stream();
    if (docs.empty()) {
        throw kcl_lib::KclError("kcl: invalid JSON result: <empty document>");
    }
    return docs.front();
#endif
}

/// The boolean predicate is `is_boolean` on nlohmann and `is_bool` on the
/// bundled type.
inline bool value_is_bool(const kcl_lib::JsonValue& value)
{
#ifdef KCL_LIB_HAS_NLOHMANN
    return value.is_boolean();
#else
    return value.is_bool();
#endif
}

/// Integer view of a JSON number.
inline long long value_as_int(const kcl_lib::JsonValue& value)
{
#ifdef KCL_LIB_HAS_NLOHMANN
    return value.get<long long>();
#else
    return value.as_int();
#endif
}

/// Number predicate. `is_number` covers integers, unsigneds and floats on
/// nlohmann and is the bundled type's own spelling.
inline bool value_is_int(const kcl_lib::JsonValue& value)
{
    return value.is_number();
}

/// String member, or `fallback` when absent or another type. Mirrors the
/// `args.path("k")` defaulting the other runners rely on.
std::string json_string_or(const kcl_lib::JsonValue& parent, const std::string& key,
                           const std::string& fallback = std::string())
{
    const kcl_lib::JsonValue* member = kcl_lib::detail::json_find(parent, key);
    if (member == nullptr) {
        return fallback;
    }
    std::string text;
    if (!kcl_lib::detail::json_string(*member, text)) {
        return fallback;
    }
    return text;
}

bool json_bool_or(const kcl_lib::JsonValue& parent, const std::string& key, bool fallback = false)
{
    const kcl_lib::JsonValue* member = kcl_lib::detail::json_find(parent, key);
    if (member == nullptr || !value_is_bool(*member)) {
        return fallback;
    }
    std::string text;
    kcl_lib::detail::json_scalar_text(*member, text);
    return text == "true";
}

/// Every string element of an array member, skipping absent/non-array members.
/// The manifest carries `duration` as a JSON string holding an unsigned
/// integer, so callers that want a number parse it themselves.
std::vector<std::string> json_string_array(const kcl_lib::JsonValue& parent, const std::string& key)
{
    std::vector<std::string> values;
    const kcl_lib::JsonValue* member = kcl_lib::detail::json_find(parent, key);
    if (member == nullptr || !member->is_array()) {
        return values;
    }
    kcl_lib::detail::for_each_item(*member, [&values](const kcl_lib::JsonValue& item) {
        std::string text;
        if (kcl_lib::detail::json_string(item, text)) {
            values.push_back(std::move(text));
        }
    });
    return values;
}

const kcl_lib::JsonValue* member_or_null(const kcl_lib::JsonValue& parent, const std::string& key)
{
    return kcl_lib::detail::json_find(parent, key);
}

// ---------------------------------------------------------------------------
// Manifest access
// ---------------------------------------------------------------------------

std::string read_file(const fs::path& path)
{
    std::ifstream stream(path, std::ios::binary);
    if (!stream) {
        throw std::runtime_error("cannot open " + path.string());
    }
    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return buffer.str();
}

/// Repository root: the parent of the directory holding `cases.json`, twice
/// over (`<root>/tests/consistency/cases.json`).
fs::path repo_root()
{
    return fs::absolute(KCL_CONSISTENCY_CASES).lexically_normal().parent_path().parent_path()
        .parent_path();
}

/// One manifest entry, borrowed from the parsed document.
struct Case {
    std::string name;
    std::string rpc;
    bool new_core = false;
    const kcl_lib::JsonValue* args = nullptr;
    const kcl_lib::JsonValue* expect = nullptr;
};

kcl_lib::JsonValue manifest;
std::vector<Case> cases;

/// Load and index the manifest once, checking the version the runner knows.
bool load_manifest()
{
    const fs::path path = KCL_CONSISTENCY_CASES;
    std::ifstream probe(path, std::ios::binary);
    CHECK(probe.good());

    manifest = parse_json_document(read_file(path));

    const kcl_lib::JsonValue* version = kcl_lib::detail::json_find(manifest, "version");
    CHECK(version != nullptr);
    CHECK(value_is_int(*version));
    CHECK(value_as_int(*version) == 1);

    const kcl_lib::JsonValue* list = kcl_lib::detail::json_find(manifest, "cases");
    CHECK(list != nullptr);
    CHECK(list->is_array());
    CHECK(list->size() > 0);

    // `cases` is file-scope state, so the lambda captures nothing.
    kcl_lib::detail::for_each_item(*list, [](const kcl_lib::JsonValue& entry) {
        Case c;
        c.name = json_string_or(entry, "name");
        c.rpc = json_string_or(entry, "rpc");
        c.new_core = json_bool_or(entry, "new_core");
        c.args = member_or_null(entry, "args");
        c.expect = member_or_null(entry, "expect");
        cases.push_back(std::move(c));
    });
    return true;
}

const Case* find_case(const std::string& name)
{
    for (const Case& c : cases) {
        if (c.name == name) {
            return &c;
        }
    }
    return nullptr;
}

// ---------------------------------------------------------------------------
// RPC surface
// ---------------------------------------------------------------------------

/// Names `BuiltinService.ListMethod` advertises, resolved once per run. A core
/// that predates the RPC throws instead of answering; treat that as an empty
/// surface so `new_core` cases skip rather than fail.
std::set<std::string>& methods()
{
    static std::set<std::string> names;
    static bool resolved = false;
    if (!resolved) {
        resolved = true;
        try {
            for (const rust::String& name : kcl_lib::list_method().method_name_list) {
                // `rust::String`'s conversion to std::string is explicit and
                // its `c_str()` is non-const, so go through data()/size().
                names.insert(std::string(name.data(), name.size()));
            }
        } catch (const std::exception& e) {
            std::cerr << "list_method unavailable (" << e.what() << "); new_core cases will skip"
                      << std::endl;
        }
    }
    return names;
}

/// Skip the case when the linked core does not serve the RPC it needs.
void require_supported(const Case& c)
{
    if (c.new_core && methods().count(c.rpc) == 0) {
        throw SkipCase("core does not list " + c.rpc + " (old core)");
    }
}

// ---------------------------------------------------------------------------
// Assertions
// ---------------------------------------------------------------------------

/// Line-by-line diff of two payloads, in the `--- expected / +++ actual` shape
/// the java runner uses. A single `EXPECT_EQ`-style comparison of a generated
/// OpenAPI spec or Markdown document is unreadable in a failure log; this keeps
/// the mismatch visible line by line.
std::string diff(const std::string& expected, const std::string& actual)
{
    // Split on '\n' keeping the trailing empty field, so a missing or extra
    // final newline shows up as a `-`/`+` line rather than silently matching.
    auto split = [](const std::string& text, std::vector<std::string>& out) {
        std::string current;
        for (char ch : text) {
            if (ch == '\n') {
                out.push_back(current);
                current.clear();
            } else {
                current.push_back(ch);
            }
        }
        out.push_back(current);
    };
    std::vector<std::string> el;
    std::vector<std::string> al;
    split(expected, el);
    split(actual, al);

    std::ostringstream out;
    out << "--- expected\n+++ actual\n";
    const size_t n = std::max(el.size(), al.size());
    for (size_t i = 0; i < n; ++i) {
        const bool has_e = i < el.size();
        const bool has_a = i < al.size();
        if (has_e && has_a && el[i] == al[i]) {
            out << "  " << el[i] << '\n';
            continue;
        }
        if (has_e) {
            out << "- " << el[i] << '\n';
        }
        if (has_a) {
            out << "+ " << al[i] << '\n';
        }
    }
    return out.str();
}

/// Compare one `expect` field against the value the runtime produced, printing
/// the diff on mismatch. Returns false instead of asserting so the caller can
/// keep its `return false` CHECK flow.
bool field_matches(const std::string& case_name, const std::string& field,
                   const std::string& expected, const std::string& actual)
{
    if (expected == actual) {
        return true;
    }
    std::cerr << "consistency case `" << case_name << "` field `" << field << "` mismatch:\n"
              << diff(expected, actual);
    return false;
}

#define CHECK_FIELD(case_name, field, expected, actual) \
    do { \
        if (!field_matches((case_name), (field), (expected), (actual))) { \
            return false; \
        } \
    } while (0)

/// `expect.<field>` as a string, failing when the manifest omits it entirely.
bool expect_string(const Case& c, const std::string& field, std::string& out)
{
    const kcl_lib::JsonValue* value = member_or_null(*c.expect, field);
    if (value == nullptr || !kcl_lib::detail::json_string(*value, out)) {
        std::cerr << "consistency case `" << c.name << "` has no string field `" << field << "`"
                  << std::endl;
        return false;
    }
    return true;
}

/// True when the manifest's `expect` carries `field`; used so the runner
/// compares exactly the fields the manifest asks for and no others.
bool expect_has(const Case& c, const std::string& field)
{
    return member_or_null(*c.expect, field) != nullptr;
}

// ---------------------------------------------------------------------------
// Argument construction
// ---------------------------------------------------------------------------

/// `ParseProgramArgs.paths` entries are pinned repo-relative by the generator;
/// absolute entries are kept as-is. Resolving here is what keeps the runner
/// independent of the working directory.
rust::Vec<rust::String> absolute_paths(const kcl_lib::JsonValue& parse_args)
{
    rust::Vec<rust::String> paths;
    for (const std::string& raw : json_string_array(parse_args, "paths")) {
        const fs::path entry(raw);
        const fs::path resolved = entry.is_absolute() ? entry : repo_root() / entry;
        paths.push_back(rust::String(resolved.lexically_normal().string()));
    }
    return paths;
}

rust::Vec<rust::String> as_rust_strings(const std::vector<std::string>& values)
{
    rust::Vec<rust::String> out;
    for (const std::string& value : values) {
        out.push_back(rust::String(value));
    }
    return out;
}

/// Only the fields the ExecProgram cases set are forwarded; the runtime treats
/// every omitted field as its default, which is what the golden results were
/// produced with.
kcl_lib::ExecProgramArgs build_exec_args(const kcl_lib::JsonValue& args)
{
    kcl_lib::ExecProgramArgs exec {};
    exec.work_dir = rust::String(json_string_or(args, "work_dir"));
    exec.k_filename_list = as_rust_strings(json_string_array(args, "k_filename_list"));
    exec.k_code_list = as_rust_strings(json_string_array(args, "k_code_list"));
    exec.overrides = as_rust_strings(json_string_array(args, "overrides"));
    return exec;
}

kcl_lib::ParseProgramArgs build_parse_args(const kcl_lib::JsonValue& node)
{
    kcl_lib::ParseProgramArgs parse {};
    parse.paths = absolute_paths(node);
    parse.sources = as_rust_strings(json_string_array(node, "sources"));
    return parse;
}

// ---------------------------------------------------------------------------
// Cases
// ---------------------------------------------------------------------------

bool run_case(const std::string& name)
{
    const Case* found = find_case(name);
    if (found == nullptr) {
        std::cerr << "consistency case not found in manifest: " << name << std::endl;
        return false;
    }
    const Case& c = *found;
    const kcl_lib::JsonValue& args = *c.args;
    require_supported(c);

    if (c.rpc == "KclService.Ping") {
        kcl_lib::PingArgs ping {};
        ping.value = rust::String(json_string_or(args, "value"));
        const std::string expected = json_string_or(*c.expect, "value");
        CHECK_FIELD(name, "value", expected, std::string(kcl_lib::ping(ping).value));
        return true;
    }

    if (c.rpc == "KclService.ExecProgram") {
        const auto result = kcl_lib::exec_program(build_exec_args(args));
        std::string expected;
        if (expect_has(c, "yaml_result")) {
            CHECK(expect_string(c, "yaml_result", expected));
            CHECK_FIELD(name, "yaml_result", expected, std::string(result.yaml_result));
        }
        if (expect_has(c, "json_result")) {
            CHECK(expect_string(c, "json_result", expected));
            CHECK_FIELD(name, "json_result", expected, std::string(result.json_result));
        }
        return true;
    }

    if (c.rpc == "KclService.FormatCode") {
        kcl_lib::FormatCodeArgs format {};
        format.source = rust::String(json_string_or(args, "source"));
        const auto result = kcl_lib::format_code(format);
        std::string expected;
        CHECK(expect_string(c, "formatted", expected));
        CHECK_FIELD(name, "formatted", expected, std::string(result.formatted));
        return true;
    }

    if (c.rpc == "KclService.ValidateCode") {
        kcl_lib::ValidateCodeArgs validate {};
        validate.data = rust::String(json_string_or(args, "data"));
        validate.code = rust::String(json_string_or(args, "code"));
        validate.datafile = rust::String(json_string_or(args, "datafile"));
        validate.file = rust::String(json_string_or(args, "file"));
        validate.schema = rust::String(json_string_or(args, "schema"));
        validate.attribute_name = rust::String(json_string_or(args, "attribute_name"));
        validate.format = rust::String(json_string_or(args, "format"));
        const auto result = kcl_lib::validate_code(validate);

        const kcl_lib::JsonValue* want = member_or_null(*c.expect, "success");
        CHECK(want != nullptr);
        CHECK(value_is_bool(*want));
        std::string want_text;
        kcl_lib::detail::json_scalar_text(*want, want_text);
        if (result.success != (want_text == "true")) {
            std::cerr << "consistency case `" << name << "` field `success` mismatch:\n"
                      << "--- expected\n" << want_text << "\n+++ actual\n"
                      << (result.success ? "true" : "false") << std::endl;
            return false;
        }
        // Only compare `err_message` when the manifest asks for it:
        // `validate_code_invalid` pins the flag alone.
        if (expect_has(c, "err_message")) {
            std::string expected;
            CHECK(expect_string(c, "err_message", expected));
            CHECK_FIELD(name, "err_message", expected, std::string(result.err_message));
        }
        return true;
    }

    if (c.rpc == "KclService.FormatTestReport") {
        kcl_lib::FormatTestReportArgs report {};
        report.result.has_value = true;
        const kcl_lib::JsonValue* infos = member_or_null(args, "result");
        CHECK(infos != nullptr);
        const kcl_lib::JsonValue* list = member_or_null(*infos, "info");
        CHECK(list != nullptr);
        kcl_lib::detail::for_each_item(*list, [&report](const kcl_lib::JsonValue& entry) {
            kcl_lib::TestCaseInfo info {};
            info.name = rust::String(json_string_or(entry, "name"));
            info.error = rust::String(json_string_or(entry, "error"));
            info.log_message = rust::String(json_string_or(entry, "log_message"));
            // The manifest carries `duration` as a JSON string holding an
            // unsigned integer, matching the proto's `uint64` field.
            info.duration = static_cast<std::uint64_t>(
                std::strtoull(json_string_or(entry, "duration", "0").c_str(), nullptr, 10));
            report.result.value.info.push_back(std::move(info));
        });
        std::string expected;
        CHECK(expect_string(c, "report", expected));
        CHECK_FIELD(name, "report", expected, std::string(kcl_lib::format_test_report(report).report));
        return true;
    }

    if (c.rpc == "KclService.GenerateToml") {
        kcl_lib::GenerateTomlArgs generate {};
        generate.exec_args.has_value = true;
        const kcl_lib::JsonValue* exec = member_or_null(args, "exec_args");
        CHECK(exec != nullptr);
        generate.exec_args.value = build_exec_args(*exec);
        generate.sort_keys = json_bool_or(args, "sort_keys");
        std::string expected;
        CHECK(expect_string(c, "toml", expected));
        CHECK_FIELD(name, "toml", expected, std::string(kcl_lib::generate_toml(generate).toml));
        return true;
    }

    if (c.rpc == "KclService.GenerateKcl") {
        kcl_lib::GenerateKclArgs generate {};
        generate.source = rust::String(json_string_or(args, "source"));
        generate.filename = rust::String(json_string_or(args, "filename"));
        generate.format = rust::String(json_string_or(args, "format"));
        std::string expected;
        CHECK(expect_string(c, "kcl", expected));
        CHECK_FIELD(name, "kcl", expected, std::string(kcl_lib::generate_kcl(generate).kcl));
        return true;
    }

    if (c.rpc == "KclService.GenerateOpenAPI") {
        kcl_lib::GenerateOpenAPIArgs generate {};
        const kcl_lib::JsonValue* parse = member_or_null(args, "parse_args");
        CHECK(parse != nullptr);
        generate.parse_args.has_value = true;
        generate.parse_args.value = build_parse_args(*parse);
        generate.version = rust::String(json_string_or(args, "version"));
        std::string expected;
        CHECK(expect_string(c, "spec", expected));
        CHECK_FIELD(name, "spec", expected, std::string(kcl_lib::generate_openapi(generate).spec));
        return true;
    }

    if (c.rpc == "KclService.GenerateProto") {
        kcl_lib::GenerateProtoArgs generate {};
        const kcl_lib::JsonValue* parse = member_or_null(args, "parse_args");
        CHECK(parse != nullptr);
        generate.parse_args.has_value = true;
        generate.parse_args.value = build_parse_args(*parse);
        generate.package = rust::String(json_string_or(args, "package"));
        std::string expected;
        CHECK(expect_string(c, "proto", expected));
        CHECK_FIELD(name, "proto", expected, std::string(kcl_lib::generate_proto(generate).proto));
        return true;
    }

    if (c.rpc == "KclService.GenerateDoc") {
        kcl_lib::GenerateDocArgs generate {};
        const kcl_lib::JsonValue* parse = member_or_null(args, "parse_args");
        CHECK(parse != nullptr);
        generate.parse_args.has_value = true;
        generate.parse_args.value = build_parse_args(*parse);
        generate.format = rust::String(json_string_or(args, "format"));
        std::string expected;
        CHECK(expect_string(c, "content", expected));
        CHECK_FIELD(
            name, "content", expected, std::string(kcl_lib::generate_doc(generate).content));
        return true;
    }

    std::cerr << "no runner support for rpc " << c.rpc << " (case " << name << ")" << std::endl;
    return false;
}

} // namespace

int main()
{
    // Every case in the manifest, in manifest order, so a case added upstream
    // is picked up without touching this file.
    const std::vector<std::pair<std::string, bool (*)()>> tests = { {
        "manifest", []() { return load_manifest(); },
    } };

    int failed = 0;
    int skipped = 0;
    int passed = 0;

    try {
        for (const auto& [name, fn] : tests) {
            try {
                if (fn()) {
                    std::cout << "[PASS] " << name << std::endl;
                } else {
                    std::cout << "[FAIL] " << name << std::endl;
                    ++failed;
                }
            } catch (const std::exception& e) {
                std::cerr << "[FAIL] " << name << " threw: " << e.what() << std::endl;
                ++failed;
            }
        }

        if (failed == 0) {
            for (const Case& c : cases) {
                try {
                    if (run_case(c.name)) {
                        std::cout << "[PASS] " << c.name << " (" << c.rpc << ")" << std::endl;
                        ++passed;
                    } else {
                        std::cout << "[FAIL] " << c.name << " (" << c.rpc << ")" << std::endl;
                        ++failed;
                    }
                } catch (const SkipCase& e) {
                    std::cout << "[SKIP] " << c.name << " (" << c.rpc << "): " << e.what()
                              << std::endl;
                    ++skipped;
                } catch (const std::exception& e) {
                    std::cerr << "[FAIL] " << c.name << " (" << c.rpc << ") threw: " << e.what()
                              << std::endl;
                    ++failed;
                }
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "consistency manifest could not be loaded: " << e.what() << std::endl;
        return 1;
    }

    std::cout << passed << " passed, " << skipped << " skipped, " << failed << " failed out of "
              << cases.size() << " consistency cases" << std::endl;
    if (failed > 0) {
        return 1;
    }
    return 0;
}
